fn parse_transaction(record: &[String], line_number: usize) -> Result<Transaction, String> {
    if record.len() != 4 {
        return Err(format!(
            "Line {}: Expected 4 fields, got {}",
            line_number,
            record.len()
        ));
    }

    let date_str = &record[0];
    let description = record[1].clone();
    let amount_str = &record[2];
    let currency = record[3].clone();

    let date = NaiveDate::parse_from_str(date_str, "%Y-%m-%d")
        .map_err(|e| format!("Line {}: Invalid date '{}': {}", line_number, date_str, e))?;

    let amount: f64 = amount_str
        .parse()
        .map_err(|e| format!("Line {}: Invalid amount '{}': {}", line_number, amount_str, e))?;

    if currency.is_empty() {
        return Err(format!("Line {}: Currency is empty", line_number));
    }

    Ok(Transaction {
        date,
        description,
        amount,
        currency,
    })
}

